<script setup lang="ts">
import {onBeforeUnmount,onMounted,ref,watch} from 'vue';import L from 'leaflet';import type {Journey,Vehicle} from '../types';
const props=defineProps<{active:boolean;journey:Journey|null}>();const target=ref<HTMLElement>();const failed=ref(false);const stale=ref(false);let map:L.Map|undefined;let source:EventSource|undefined;let timer:number|undefined;let pollTimer:number|undefined;let markers:L.CircleMarker[]=[];let routeLayers:L.Layer[]=[];
const colors=['#397d8c','#176a9b','#537a3b','#a44a2d','#67558f'];
function clearRoute(){routeLayers.forEach(layer=>layer.remove());routeLayers=[]}
function renderJourney(journey:Journey|null){if(!map)return;clearRoute();if(!journey)return;const bounds:L.LatLngBoundsExpression=[];journey.legs.forEach((leg,index)=>{const points=leg.geometry?.map(point=>[point.latitude,point.longitude] as [number,number])??[];if(points.length<2)return;points.forEach(point=>bounds.push(point));const transit=leg.mode==='TRANSIT';const layer=L.polyline(points,{color:transit?colors[index%colors.length]:'#397d8c',weight:transit?6:4,dashArray:transit?undefined:'3 8',lineCap:'round'}).bindTooltip(transit?`${leg.line} · ${leg.direction}`:'Caminhada aproximada');layer.addTo(map!);routeLayers.push(layer)});const stops: [number,number][]=[];journey.legs.forEach(leg=>leg.geometry?.length&&stops.push([leg.geometry[0].latitude,leg.geometry[0].longitude],[leg.geometry.at(-1)!.latitude,leg.geometry.at(-1)!.longitude]));if(stops.length){stops.forEach((point,index)=>{const marker=L.circleMarker(point,{radius:index===0||index===stops.length-1?8:6,color:index===0?'#173d32':'#b94724',fillColor:'#fffdf7',fillOpacity:1,weight:2}).bindTooltip(index===0?'Embarque':index===stops.length-1?'Desembarque':'Conexão');marker.addTo(map!);routeLayers.push(marker)});map.fitBounds(stops,{padding:[34,34],maxZoom:14})}}
function renderVehicles(list:Vehicle[]){markers.forEach(m=>m.remove());markers=list.map(v=>L.circleMarker([v.latitude,v.longitude],{radius:7,color:'#fff',weight:2,fillColor:'#b94724',fillOpacity:1}).bindTooltip(`${v.vehicleId} · ${v.line}<br>Próxima: ${v.nextStop} · ${v.etaMinutes} min (simulado)`).addTo(map!));stale.value=false;window.clearTimeout(timer);timer=window.setTimeout(()=>stale.value=true,12000)}
async function poll(){try{const r=await fetch('/api/simulation/vehicles');if(r.ok)renderVehicles(await r.json())}catch{stale.value=true}}
onMounted(()=>{try{map=L.map(target.value!,{zoomControl:true}).setView([-6.078,-49.892],13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap',maxZoom:19}).on('tileerror',()=>failed.value=true).addTo(map);renderJourney(props.journey);source=new EventSource('/api/simulation/stream');source.addEventListener('vehicles',e=>renderVehicles(JSON.parse((e as MessageEvent).data)));source.onerror=()=>{source?.close();stale.value=true;poll();pollTimer=window.setInterval(poll,10000)}}catch{failed.value=true}});watch(()=>props.journey,j=>{renderJourney(j);window.setTimeout(()=>map?.invalidateSize(),80)},{deep:true});watch(()=>props.active,()=>window.setTimeout(()=>map?.invalidateSize(),100));onBeforeUnmount(()=>{source?.close();window.clearTimeout(timer);window.clearInterval(pollTimer);map?.remove()});
</script>
<template><section class="map-shell" aria-labelledby="map-title"><div class="map-toolbar"><div><h2 id="map-title">Mapa da alternativa selecionada</h2><p v-if="journey">{{ journey.label }} · {{ journey.legs.filter(leg=>leg.mode==='TRANSIT').map(leg=>leg.line).join(' + ') || 'A pé' }}</p><p v-else>Busque um trajeto para desenhar suas etapas.</p></div><span v-if="stale" class="status stale">Posição desatualizada</span><span v-else class="status">Simulação ativa</span></div><div ref="target" class="map" :class="{hidden:failed}" aria-label="Mapa interativo da alternativa selecionada"></div><div v-if="!failed" class="map-legend" aria-label="Legenda do trajeto"><span><i class="transit-line"></i>Ônibus</span><span><i class="walking"></i>Caminhada aproximada</span><span><i class="transfer-dot"></i>Embarque ou conexão</span></div><div v-if="failed" class="map-fallback"><strong>Camada cartográfica indisponível</strong><p>As etapas e horários continuam acessíveis na lista ao lado.</p></div></section></template>
